/* Read-only bounded region metadata; never reads target payload or changes VM. */
#include <mach/mach.h>
#include <mach/vm_region.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <limits.h>
#include <unistd.h>
struct result {vm_address_t lo;vm_size_t size;vm_region_basic_info_data_t basic;vm_region_extended_info_data_t ext;int bk,ek;unsigned bc,ec;};
static unsigned parse(const char*s,int base){char*end;unsigned long v;errno=0;v=strtoul(s,&end,base);if(errno||!s[0]||*end||v>UINT_MAX){fprintf(stderr,"invalid argument\n");exit(2);}return v;}
static void query(task_t task,unsigned a,struct result*r){vm_address_t x=a,y=a;vm_size_t n=0,m=0;mach_msg_type_number_t bc=VM_REGION_BASIC_INFO_COUNT,ec=VM_REGION_EXTENDED_INFO_COUNT;mach_port_t object=MACH_PORT_NULL;memset(r,0,sizeof(*r));r->bk=vm_region(task,&x,&n,VM_REGION_BASIC_INFO,(vm_region_info_t)&r->basic,&bc,&object);if(object!=MACH_PORT_NULL)mach_port_deallocate(mach_task_self(),object);object=MACH_PORT_NULL;r->ek=vm_region(task,&y,&m,VM_REGION_EXTENDED_INFO,(vm_region_info_t)&r->ext,&ec,&object);if(object!=MACH_PORT_NULL)mach_port_deallocate(mach_task_self(),object);r->bc=bc;r->ec=ec;r->lo=x;r->size=n;if(r->bk==KERN_SUCCESS&&r->ek==KERN_SUCCESS&&(x!=y||n!=m))r->ek=-1;}
static int covered(struct result*r,unsigned a,unsigned n){return r->bk==KERN_SUCCESS&&r->ek==KERN_SUCCESS&&r->bc==VM_REGION_BASIC_INFO_COUNT&&r->ec==VM_REGION_EXTENDED_INFO_COUNT&&r->size&&a>=r->lo&&n<=r->size&&a-r->lo<=r->size-n;}
static int stable(struct result*a,struct result*b){return a->lo==b->lo&&a->size==b->size&&a->basic.protection==b->basic.protection&&a->basic.max_protection==b->basic.max_protection&&a->basic.shared==b->basic.shared&&a->basic.reserved==b->basic.reserved&&a->basic.offset==b->basic.offset&&a->basic.inheritance==b->basic.inheritance&&a->ext.protection==b->ext.protection&&a->ext.user_tag==b->ext.user_tag&&a->ext.external_pager==b->ext.external_pager&&a->ext.share_mode==b->ext.share_mode&&a->ext.shadow_depth==b->ext.shadow_depth;}
static void output(struct result*r){printf("{\"basic_status\":%d,\"extended_status\":%d,\"basic_count\":%u,\"extended_count\":%u,\"region_low\":%u,\"region_size\":%u,\"protection\":%u,\"max_protection\":%u,\"shared\":%u,\"reserved\":%u,\"object_offset\":%u,\"inheritance\":%u,\"extended_protection\":%u,\"user_tag\":%u,\"external_pager\":%u,\"share_mode\":%u,\"shadow_depth\":%u}",r->bk,r->ek,r->bc,r->ec,(unsigned)r->lo,(unsigned)r->size,r->basic.protection,r->basic.max_protection,r->basic.shared,r->basic.reserved,r->basic.offset,r->basic.inheritance,r->ext.protection,r->ext.user_tag,r->ext.external_pager,r->ext.share_mode,r->ext.shadow_depth);}
int main(int argc,char**argv){unsigned pid,i,n,a,errors=0;task_t task;vm_address_t fixture=0;int selftest=argc==2&&!strcmp(argv[1],"--self-test");if(selftest){pid=getpid();task=mach_task_self();if(vm_allocate(task,&fixture,4096,VM_FLAGS_ANYWHERE)!=KERN_SUCCESS)return 3;memset((void*)fixture,0x5a,4096);argc=4;}else{if(argc<4||argc>26||argc%2)return 2;pid=parse(argv[1],10);if(pid<2||pid>INT_MAX)return 2;if(task_for_pid(mach_task_self(),pid,&task)!=KERN_SUCCESS)return 3;}
 printf("{\"schema\":1,\"pid\":%u,\"fixture\":%s,\"payload_reads\":0,\"vm_mutations\":%u,\"regions\":[",pid,selftest?"true":"false",selftest?1:0);
 for(i=2;i<(unsigned)argc;i+=2){struct result b,c;a=selftest?(unsigned)fixture:parse(argv[i],16);n=selftest?164:parse(argv[i+1],16);if(a<4096||!n||n>256||a>UINT_MAX-n){errors++;printf("%s{\"argument_invalid\":true}",i==2?"":",");continue;}query(task,a,&b);query(task,a,&c);{int ok=covered(&b,a,n)&&covered(&c,a,n)&&stable(&b,&c);if(!ok)errors++;printf("%s{\"address\":%u,\"bytes\":%u,\"covered_stable\":%s,\"before\":",i==2?"":",",a,n,ok?"true":"false");output(&b);printf(",\"after\":");output(&c);printf("}");}}
 printf("],\"errors\":%u,\"region_metadata_not_object_identity\":true}\n",errors);if(selftest)vm_deallocate(task,fixture,4096);else mach_port_deallocate(mach_task_self(),task);return errors?4:0;}
